input.command:
entire brain recall "npm override simple-git scripts/bench engine-verification-pins re-pin" --json 2>&1 | python3 -c 'import sys,json
raw=sys.stdin.read()
try: d=json.loads(raw)
except Exception: print(raw[:3000]); sys.exit()
items=d.get("results") or d.get("memories") or d.get("facts") or d.get("items") or []
for it in items[:6]:
  print(json.dumps({k:it.get(k) for k in ("id","created_at","path","text","content","body","score") if it.get(k) is not None})[:900]); print()
if not items: print(raw[:3000])'

