input.command:
rg -n "embed-server|scripts/bench" --glob '!scripts/bench/**' -l | head -30; echo ---; python3 -c '
import json;d=json.load(open("benchmarks/agent-brain/confirmatory/engine-verification-pins.json"))
def walk(o,p=""):
  if isinstance(o,dict):
    for k,v in o.items(): walk(v,p+"."+k)
  elif isinstance(o,list):
    for i,v in enumerate(o[:3]): walk(v,p+f"[{i}]")
  else:
    s=str(o)
    if any(x in (p+s).lower() for x in ("bench","node","llama","package","gguf","embed","runtime","engine")): print(p, "=", s[:100])
walk(d)' | head -40

